SET @lookupTypeId = (SELECT lookup_type_id FROM lookup_type WHERE lookup_type_code = 'TENANT_SERVICE_TYPES');
UPDATE lookup_type
SET parent_lookup_type_id = @lookupTypeId
WHERE lookup_type_code = 'SUB_PRODUCT_TYPE';

UPDATE lookup_type
SET category = 'Product Catalog'
WHERE lookup_type_code = 'TENANT_SERVICE_TYPES';

