UPDATE milestone_display_set_include
SET description = 'Auto-populated when the "Provisioner" value is populated for the first time'
WHERE milestone_id = (SELECT milestone_id FROM milestone WHERE milestone_code = 'ENGINEER_ASSIGNED');

UPDATE milestone_display_set_include
SET description = 'Targeted or requested date by the customer for completed service delivery'
WHERE milestone_id = (SELECT milestone_id FROM milestone WHERE milestone_code = 'CUSTOMER_REQUESTED_INSTALL');

ALTER TABLE company_config_property
    modify column description varchar(250) NULL;

UPDATE company_config_property
SET description = 'Sends an email to the i90 provisioner assignee''s registered email that an order has been assigned to them.  This will not activate when assigning orders to yourself.'
WHERE config_property_key = 'EMAIL_PROVISIONER_ON_ORDER_ASSIGNMENT';

UPDATE company_config_property
SET description = 'Sends an email to the i90 Project Manager assignee''s  registered email that an order has been assigned to them.  This will not activate when assigning orders to yourself.'
WHERE config_property_key = 'EMAIL_PROJECT_MANAGER_ON_ORDER_ASSIGNMENT';

UPDATE company_config_property
SET description = 'Checking "True" will enforce the "client service ID" field to be a unique value.'
WHERE config_property_key = 'CLIENT_ID_UNIQUE_CONSTRAINT';

UPDATE company_config_property
SET description = 'Entering a value sets it as the default value in the "Level of Effort" field on the location level for every new location order that is created.'
WHERE config_property_key = 'LOE_DEFAULT';

UPDATE company_config_property
SET description = 'Multi-selection of which service types you want available for orders.'
WHERE config_property_key = 'ASSIGNED_SERVICE_TYPES';

UPDATE company_config_property
SET description = 'Checking False forces the user to enter a custom service ID for every service.  Checking True will instruct i90 to create a unique ID automatically.'
WHERE config_property_key = 'AUTO_CREATE_CLIENT_SERVICE_ID';

UPDATE company_config_property
SET description = 'Checking True will force i90 to search for existing location ID''s When new orders are created.  If matches are found, i90 will add the new service to the existing order matched by location ID.  Checking False will create a new order, always.'
WHERE config_property_key = 'COMBINE_OPEN_ORDERS';

UPDATE company_config_property
SET description = 'Checking True will default every dispute note entered to be an "internal only" note visible only to users with "write" permissions.  Checking False will default the notes to be available to all user types.'
WHERE config_property_key = 'DISPUTE_NOTE_INTERNAL_ONLY_DEFAULT';

UPDATE company_config_property
SET description = 'Checking True will default every service note entered to be an "internal only" note visible only to users with "write" permissions.  Checking False will default the notes to be available to all user types.',
config_property_key = 'SERVICE_NOTE_INTERNAL_ONLY_DEFAULT'
WHERE config_property_key = 'NOTE_INTERNAL_ONLY_DEFAULT';

